import React from "react";
import headerBg from '../img/header-bg.png'; 

const Home = () => {
  return (
    <div
      style={{
        width: '600px',
        height: '400px',
        textAlign: "center",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        minHeight: "100vh",
        gap: "20px",        
        padding: "20px",
        margin: "0 auto"
      }}
    >
      <h1>Hi, my name is <strong>John Doe</strong></h1>
      <h2>a frontend developer</h2>
      <h3>with passion for learning and creating.</h3>

      <img
        src={headerBg} 
        alt="Profile"
        style={{ width: "200px" }} // border-radius убран
      />

      <a href="CV.pdf" target="_blank" rel="noopener noreferrer">
        <button
          style={{
            padding: "10px 20px",
            fontSize: "16px",
            cursor: "pointer",
            backgroundColor: "#4CAF50",
            color: "white",
            border: "none",
          }}
        >
          Download CV
        </button>
      </a>
    </div>
  );
};

export default Home;
